mapper.select:
SELECT tenant_id, link_id, application_id, domain_id
FROM shortlink_ownership_backfill_items
WHERE tenant_id = #{tenantId}
  AND status IN ('PENDING', 'RETRYABLE')
ORDER BY CASE status WHEN 'PENDING' THEN 0 ELSE 1 END, updated_at ASC, link_id ASC
LIMIT #{limit}

mapper.update:
UPDATE shortlink_ownership_backfill_items
SET last_error = CASE
        WHEN status IN ('RECONCILED', 'ALREADY_RECONCILED', 'PERMANENT_FAILURE', 'NOT_FOUND') THEN last_error
        ELSE #{lastError}
    END,
    status = CASE
        WHEN status IN ('RECONCILED', 'ALREADY_RECONCILED', 'PERMANENT_FAILURE', 'NOT_FOUND') THEN status
        ELSE #{status}
    END,
    attempts = attempts + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId}
  AND link_id = #{linkId}
